    return G
G=load(); print(sorted(G))
def f(i):
    H,W=len(i),len(i[0]); out=[row[:] for row in i]
    from collections import Counter
    cnt=Counter(x for r in i for x in r); bg=cnt.most_common(1)[0][0]
    ms=[(r,c) for r in range(H) for c in range(W) if i[r][c]!=bg]
    for r in range(H):
        for c in range(W):
            if any(abs(r-fr)<=1 and abs(c-fc)<=1 for fr,fc in ms):
                out[r][c]=1 if i[r][c]==bg else i[r][c]
    return out
